import React, { useEffect, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { QueryClient, QueryClientProvider, useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { AlertTriangle, Bell, Bot, Building2, ChevronRight, CircleGauge, Clock3, Database, Download, Droplets, Fan, Gauge, LayoutDashboard, Lightbulb, LogOut, MapPinned, MapPin, Menu, Power, Save, ShieldCheck, SlidersHorizontal, Thermometer, UserRound, Users, X, Zap } from 'lucide-react';
import { api, login, setToken } from './services/api';
import './styles.css';

const queryClient = new QueryClient();
const nav = [
  ['Overview', LayoutDashboard], ['Buildings', Building2], ['Building Map', MapPinned], ['Environment', Thermometer], ['HVAC Control', Fan], ['Energy', Zap], ['AI Insights', Bot], ['Maintenance', WrenchIcon], ['Alerts', AlertTriangle], ['Scheduling', Gauge], ['Service Requests', Lightbulb], ['Reports', CircleGauge], ['Sensors', Droplets], ['Users', Users], ['Settings', Gauge]
] as const;
function WrenchIcon(props: { size?: number }) { return <span {...props}>🔧</span>; }

type Section = typeof nav[number][0];
function App() {
  const [user, setUser] = useState<{ name: string; role: string } | null>(null);
  const [section, setSection] = useState<Section>('Overview');
  const [mobileNav, setMobileNav] = useState(false);
  useEffect(() => { const stored = localStorage.getItem('smarthvac_token'); if (stored) setUser({ name: 'Jamie Chen', role: 'Facility manager' }); }, []);
  if (!user) return <Login onLogin={(next) => setUser(next)} />;
  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? 'open' : ''}`}><div className="brand"><span className="brand-mark">◒</span><span>Smart<span>HVAC</span></span><button className="close-mobile" onClick={() => setMobileNav(false)}><X size={18} /></button></div><p className="sidebar-kicker">BUILDING INTELLIGENCE</p><nav>{nav.map(([label, Icon]) => <button className={section === label ? 'active' : ''} key={label} onClick={() => { setSection(label); setMobileNav(false); }}><Icon size={17} /><span>{label}</span>{label === 'Alerts' && <b>3</b>}</button>)}</nav><div className="sidebar-foot"><span className="online-dot" /> Demo telemetry live <button onClick={() => { localStorage.removeItem('smarthvac_token'); setToken(null); setUser(null); }} title="Log out"><LogOut size={15} /></button></div></aside>
    <main className="main"><header className="topbar"><button className="menu-button" onClick={() => setMobileNav(true)}><Menu size={20} /></button><div><span className="crumb">SmartHVAC /</span><strong>{section}</strong></div><div className="top-user"><span className="live-pill"><i /> LIVE</span><span className="avatar">JC</span></div></header><div className="content"><Page section={section} /></div></main>
  </div>;
}

function Login({ onLogin }: { onLogin: (user: { name: string; role: string }) => void }) { const [email, setEmail] = useState('admin@smarthvac.local'); const [password, setPassword] = useState('demo1234'); const mutation = useMutation({ mutationFn: () => login(email, password), onSuccess: (result) => { setToken(result.access_token); onLogin(result.user); } }); return <div className="login-page"><div className="login-art"><span className="brand-mark">◒</span><h1>Intelligent HVAC for smarter buildings.</h1><p>Monitor, automate, optimize and understand every climate system from one command center.</p><div className="login-signal"><span><Thermometer size={15} /> 24.8°C</span><span><Zap size={15} /> 8.4 kW</span><span><Fan size={15} /> 94% health</span></div></div><form className="login-card" onSubmit={(event) => { event.preventDefault(); mutation.mutate(); }}><span className="eyebrow">SMART HVAC PLATFORM</span><h2>Welcome back</h2><p>Sign in to your building command center.</p><label>Email<input value={email} onChange={(event) => setEmail(event.target.value)} type="email" /></label><label>Password<input value={password} onChange={(event) => setPassword(event.target.value)} type="password" /></label><div className="login-options"><label><input type="checkbox" defaultChecked /> Remember me</label><a href="#forgot">Forgot password?</a></div>{mutation.isError && <div className="error-box">Unable to sign in. Check the API and credentials.</div>}<button className="primary-button" disabled={mutation.isPending}>{mutation.isPending ? 'Signing in...' : 'Open dashboard'} <ChevronRight size={16} /></button><small>Demo credentials: admin@smarthvac.local / demo1234</small></form></div> }

function Page({ section }: { section: Section }) { if (section === 'Overview') return <OverviewRedesign />; if (section === 'Buildings') return <BuildingsSection />; if (section === 'Building Map') return <MapSection />; if (section === 'Environment') return <EnvironmentSection />; if (section === 'HVAC Control') return <HVACControlRedesign />; if (section === 'Energy') return <EnergyRedesign />; if (section === 'Alerts') return <AlertsRedesign />; if (section === 'AI Insights') return <AIInsightsRedesign />; if (section === 'Maintenance') return <MaintenanceRedesign />; if (section === 'Scheduling') return <SchedulingRedesign />; if (section === 'Service Requests') return <ServiceRequestsRedesign />; if (section === 'Reports') return <ReportsRedesign />; if (section === 'Settings') return <SettingsRedesign />; if (section === 'Users') return <UsersSection />; if (section === 'Sensors') return <SensorsSection />; return <DashboardSection title={section} />; }
function OverviewRedesign() { const dashboard = useQuery({ queryKey: ['dashboard'], queryFn: api.dashboard, refetchInterval: 10000 }); const buildings = useQuery({ queryKey: ['locations'], queryFn: api.locations }); const alerts = useQuery({ queryKey: ['alerts'], queryFn: api.alerts }); const data = dashboard.data; const openAlerts = (alerts.data || []).filter((alert: any) => alert.status === 'OPEN'); return <><div className="overview-welcome"><div><span className="eyebrow">MONDAY · 21 SEPTEMBER 2026</span><h1>Good morning, Jamie.</h1><p>Your buildings are stable. Here is what deserves attention today.</p></div><div className="overview-live"><i /> Live network <small>Updated just now</small></div></div><div className="overview-feature-grid"><article className="overview-primary"><span className="eyebrow">NETWORK HEALTH</span><div className="overview-primary-row"><div><strong>{data?.hvac_health ?? '--'}<small>%</small></strong><p>HVAC health across your portfolio</p></div><div className="overview-ring"><span>94</span><small>score</small></div></div><div className="overview-progress"><i style={{ width: `${data?.hvac_health || 0}%` }} /></div><div className="overview-primary-foot"><span>↑ 4.2% vs last week</span><b>{data?.buildings ?? '--'} buildings monitored</b></div></article><article className="overview-energy"><div><span className="eyebrow">ENERGY TODAY</span><h2>{data ? `${(data.power * 8.6).toFixed(1)} kWh` : '--'}</h2><p>Estimated consumption</p></div><div className="overview-spark"><span /><span /><span /><span /><span /><span /><span /><span /></div><strong>{data?.energy_saved ?? '--'}% <small>saved</small></strong></article></div><div className="overview-metric-row">{[['Comfort', data ? `${data.temperature}°C` : '--', 'Network temperature', Thermometer], ['Humidity', data ? `${data.humidity}%` : '--', 'Within target range', Droplets], ['Occupancy', data?.occupancy ?? '--', 'People detected', Users], ['Open alerts', data?.open_alerts ?? '--', 'Needs review', AlertTriangle]].map(([label, value, hint, Icon]) => <article key={label as string}><span className="overview-metric-icon"><Icon size={16} /></span><div><small>{label as string}</small><strong>{value as string}</strong><em>{hint as string}</em></div></article>)}</div><div className="overview-lower-grid"><article className="panel overview-sites"><div className="panel-title"><div><span className="eyebrow">PORTFOLIO PULSE</span><h2>Building status</h2></div><span className="overview-link">View all <ChevronRight size={13} /></span></div>{(buildings.data || []).map((building: any) => <div className="overview-site-row" key={building.id}><span className={`overview-site-dot ${building.status}`} /><div><strong>{building.name.replace('SmartHVAC ', '')}</strong><small>{building.city} · {building.occupancy} occupants</small></div><span className="overview-site-temp">{building.temperature}°C</span><b className={building.status}>{building.hvacHealth}%</b></div>)}</article><article className="panel overview-alerts"><div className="panel-title"><div><span className="eyebrow">ATTENTION NEEDED</span><h2>Latest alerts</h2></div><span className="overview-alert-count">{openAlerts.length} open</span></div>{openAlerts.slice(0, 3).map((alert: any) => <div className="overview-alert-row" key={alert.id}><span className={`overview-alert-icon ${alert.severity.toLowerCase()}`}><AlertTriangle size={14} /></span><div><strong>{alert.title}</strong><small>{alert.message}</small></div></div>)}{!openAlerts.length && <div className="overview-clear"><ShieldCheck size={20} /> All systems are clear.</div>}</article></div></> }

function DashboardSection({ title }: { title: string }) { const { data, isLoading, isError } = useQuery({ queryKey: ['dashboard'], queryFn: api.dashboard, refetchInterval: 10000 }); return <><PageHeading eyebrow="BUILDING COMMAND CENTER" title={title === 'Overview' ? 'Good morning, Jamie' : title} copy="A live view of your building climate, comfort, and energy systems." /><div className="metric-grid">{[['Temperature', data ? `${data.temperature}°C` : '--', Thermometer, 'Comfortable range'], ['Humidity', data ? `${data.humidity}%` : '--', Droplets, 'Stable'], ['Occupancy', data ? data.occupancy : '--', Users, 'Across 3 buildings'], ['Power draw', data ? `${data.power} kW` : '--', Zap, 'Live telemetry'], ['Energy saved', data ? `${data.energy_saved}%` : '--', Lightbulb, 'Versus baseline'], ['HVAC health', data ? `${data.hvac_health}%` : '--', Fan, 'Portfolio average']].map(([label, value, Icon, hint]) => <article className="metric-card" key={label as string}><div className="metric-label"><span>{label as string}</span><Icon size={16} /></div><strong>{value as string}</strong><small>{hint as string}</small></article>)}</div><div className="two-column"><article className="panel chart-panel"><PanelTitle eyebrow="LIVE TELEMETRY" title="Comfort signals" /><div className="signal-visual"><span style={{ height: '54%' }} /><span style={{ height: '67%' }} /><span style={{ height: '45%' }} /><span style={{ height: '73%' }} /><span style={{ height: '61%' }} /><span style={{ height: '79%' }} /><span style={{ height: '68%' }} /><span style={{ height: '86%' }} /></div><div className="chart-legend"><span><i className="green" /> Temperature</span><span><i className="blue" /> Humidity</span><span>Last 24 hours</span></div></article><article className="panel"><PanelTitle eyebrow="ACTION REQUIRED" title="Network pulse" /><div className="pulse-list"><Pulse label="Healthy buildings" value="2 / 3" tone="good" /><Pulse label="Open alerts" value={data?.open_alerts ?? '--'} tone="warning" /><Pulse label="Demo simulator" value={isLoading ? 'Starting' : isError ? 'Offline' : 'Running'} tone={isError ? 'danger' : 'good'} /></div><button className="secondary-button">View detailed health <ChevronRight size={15} /></button></article></div></> }
function BuildingsSection() { const query = useQuery({ queryKey: ['buildings'], queryFn: api.locations, refetchInterval: 15000 }); const [search, setSearch] = useState(''); const [selected, setSelected] = useState<any>(); const buildings = (query.data || []).filter((building: any) => `${building.name} ${building.id} ${building.city} ${building.address}`.toLowerCase().includes(search.toLowerCase())); return <><PageHeading eyebrow="PORTFOLIO OPERATIONS" title="Buildings" copy="A portfolio view of every managed site, its climate, and operating health." /><div className="building-overview"><div><span className="eyebrow">MANAGED PORTFOLIO</span><strong>{query.data?.length ?? 0} buildings</strong><small>Across your SmartHVAC organization</small></div><div><span className="eyebrow">NETWORK HEALTH</span><strong>{query.data ? Math.round(query.data.reduce((sum: number, item: any) => sum + item.hvacHealth, 0) / Math.max(query.data.length, 1)) : '--'}%</strong><small>Weighted HVAC health</small></div><div><span className="eyebrow">ENERGY TODAY</span><strong>{query.data ? `${query.data.reduce((sum: number, item: any) => sum + item.energyToday, 0).toFixed(1)} kWh` : '--'}</strong><small>Live modeled consumption</small></div></div><div className="building-toolbar"><div><span className="eyebrow">LOCATION DIRECTORY</span><strong>All operating sites</strong></div><label className="building-search"><MapPin size={15} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search buildings, city, or ID" /></label></div><div className="building-layout"><div className="building-cards">{buildings.map((building: any) => <button className={`building-card-tile ${selected?.id === building.id ? 'selected' : ''}`} key={building.id} onClick={() => setSelected(building)}><div className="building-tile-top"><span className="building-code">{building.id}</span><b className={building.status}><i /> {building.status}</b></div><h2>{building.name}</h2><p><MapPin size={12} /> {building.address}, {building.city}</p><div className="building-tile-metrics"><Metric label="Temperature" value={`${building.temperature}°C`} /><Metric label="Occupancy" value={building.occupancy} /><Metric label="Power" value={`${building.power} kW`} /></div><div className="building-tile-footer"><span>HVAC health</span><strong>{building.hvacHealth}%</strong><i><em style={{ width: `${building.hvacHealth}%` }} /></i><ChevronRight size={15} /></div></button>)}</div><aside className="building-inspector">{selected ? <><span className="eyebrow">SITE INSPECTOR</span><h2>{selected.name}</h2><p>{selected.address}, {selected.city}</p><div className="inspector-status"><b className={selected.status}><i /> {selected.status}</b><span>Updated just now</span></div><div className="inspector-grid"><Metric label="Rooms" value={selected.rooms} /><Metric label="HVAC units" value={`${selected.activeUnits}/${selected.hvacUnits}`} /><Metric label="Humidity" value={`${selected.humidity}%`} /><Metric label="Energy today" value={`${selected.energyToday} kWh`} /></div><div className="inspector-actions"><button className="primary-button">Open dashboard <ChevronRight size={14} /></button><button className="secondary-button"><MapPinned size={14} /> View on map</button></div></> : <div className="empty-state"><Building2 size={28} /><strong>Choose a building</strong><p>Inspect site performance, occupancy, and HVAC health.</p></div>}</aside></div></> }

function EnvironmentSection() { const buildings = useQuery({ queryKey: ['locations'], queryFn: api.locations }); const [buildingCode, setBuildingCode] = useState(''); const query = useQuery({ queryKey: ['environment', buildingCode], queryFn: () => api.environment(buildingCode || undefined), refetchInterval: 15000 }); const rooms = query.data || []; const temperatures = rooms.filter((room: any) => room.temperature !== null); const avgTemp = temperatures.length ? temperatures.reduce((sum: number, room: any) => sum + room.temperature, 0) / temperatures.length : 0; const warmest = [...temperatures].sort((a, b) => b.temperature - a.temperature)[0]; return <><PageHeading eyebrow="COMFORT INTELLIGENCE" title="Environment" copy="Track temperature and humidity across the spaces your HVAC systems protect." /><div className="environment-controls"><div><span className="eyebrow">LIVE ENVIRONMENT</span><strong>Room conditions</strong></div><select value={buildingCode} onChange={(event) => setBuildingCode(event.target.value)}><option value="">All buildings</option>{buildings.data?.map((building: any) => <option value={building.id} key={building.id}>{building.name}</option>)}</select><div className="range-pills"><button className="active">24 hours</button><button>7 days</button><button>30 days</button></div></div><div className="environment-metrics"><article><span className="env-icon temperature"><Thermometer size={17} /></span><div><small>Average temperature</small><strong>{avgTemp ? `${avgTemp.toFixed(1)}°C` : '--'}</strong><em>Comfort target 22–26°C</em></div></article><article><span className="env-icon humidity"><Droplets size={17} /></span><div><small>Average humidity</small><strong>{temperatures.length ? '56%' : '--'}</strong><em>Optimal range 40–60%</em></div></article><article><span className="env-icon occupancy"><Users size={17} /></span><div><small>Warmest monitored room</small><strong>{warmest?.room_code || '--'}</strong><em>{warmest ? `${warmest.temperature.toFixed(1)}°C · ${warmest.building_code}` : 'No room data'}</em></div></article></div><div className="environment-layout"><article className="panel environment-chart"><PanelTitle eyebrow="TEMPERATURE PROFILE" title="Current room comfort" /><div className="env-bars">{temperatures.slice(0, 14).map((room: any) => <div className="env-bar" key={room.room_code}><span style={{ height: `${Math.min(100, Math.max(15, (room.temperature - 20) * 16))}%` }} /><small>{room.room_code}</small></div>)}</div><div className="env-chart-axis"><span>Cooler</span><span>Comfort target</span><span>Warmer</span></div></article><article className="panel environment-table"><PanelTitle eyebrow="ROOM CONDITIONS" title={`${rooms.length} monitored rooms`} /><div className="room-condition-list">{rooms.slice(0, 8).map((room: any) => <div className="room-condition" key={room.room_code}><span className="comfort-dot" /><div><strong>{room.room}</strong><small>{room.building_code} · {room.floor}</small></div><b>{room.temperature !== null ? `${room.temperature.toFixed(1)}°C` : '--'}</b><span>{room.humidity !== null ? `${room.humidity}%` : '--'}</span></div>)}</div></article></div></> }

function PageHeading({ eyebrow, title, copy }: { eyebrow: string; title: string; copy: string }) { return <div className="page-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{copy}</p></div><span className="sync-state"><i /> Data synced just now</span></div> }
function PanelTitle({ eyebrow, title }: { eyebrow: string; title: string }) { return <div className="panel-title"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2></div><ChevronRight size={17} /></div> }
function Pulse({ label, value, tone }: { label: string; value: unknown; tone: string }) { return <div className="pulse"><span className={`pulse-dot ${tone}`} /><div><strong>{label}</strong><small>Live network metric</small></div><b>{value as string}</b></div> }
function MapSection() { const { data, isLoading } = useQuery({ queryKey: ['locations'], queryFn: api.locations }); const [selected, setSelected] = useState<any>(); return <><PageHeading eyebrow="GEOGRAPHIC OPERATIONS" title="Building Intelligence Map" copy="Select a real-world location to inspect live HVAC health." /><div className="map-workspace"><div className="map-visual"><div className="map-grid" /><span className="map-city">SMART HVAC SERVICE AREA</span>{isLoading ? <div className="map-loading">Loading building locations...</div> : data?.map((building: any, index: number) => <button key={building.id} className={`map-pin ${building.status} ${selected?.id === building.id ? 'selected' : ''}`} style={{ left: `${18 + (index * 27) % 68}%`, top: `${28 + (index * 25) % 55}%` }} onClick={() => setSelected(building)} aria-label={`${building.name}, ${building.status}`}><span>●</span><strong>{building.name.replace('SmartHVAC ', '')}</strong><small>{building.hvacHealth}% health</small></button>)}</div><aside className="map-details"><PanelTitle eyebrow="BUILDING LOCATIONS" title={`${data?.length ?? 0} buildings`} />{selected ? <div className="building-card"><div className="status-line"><span>{selected.id}</span><b className={selected.status}>{selected.status}</b></div><h2>{selected.name}</h2><p>{selected.address}, {selected.city}</p><div className="detail-grid"><Metric label="Temperature" value={`${selected.temperature}°C`} /><Metric label="Occupancy" value={selected.occupancy} /><Metric label="Power" value={`${selected.power} kW`} /><Metric label="HVAC health" value={`${selected.hvacHealth}%`} /></div><button className="primary-button">Open building <ChevronRight size={15} /></button></div> : <div className="empty-state"><MapPinned size={26} /><strong>Select a building marker</strong><p>Inspect temperature, occupancy, power, and health status.</p></div>}</aside></div></> }
function Metric({ label, value }: { label: string; value: string | number }) { return <div><small>{label}</small><strong>{value}</strong></div> }
function SensorsSection() { const query = useQuery({ queryKey: ['sensors'], queryFn: api.sensors, refetchInterval: 15000 }); const [type, setType] = useState('all'); const [selected, setSelected] = useState<any>(); const sensors = query.data || []; const visible = type === 'all' ? sensors : sensors.filter((sensor: any) => sensor.type === type); const online = sensors.filter((sensor: any) => sensor.status === 'ONLINE').length; const types = [...new Set(sensors.map((sensor: any) => sensor.type))]; return <><PageHeading eyebrow="SENSOR OPERATIONS" title="Sensor health" copy="Monitor signal quality, device status, and the spaces behind every reading." /><div className="sensor-summary-grid"><article className="sensor-health-hero"><div className="health-ring"><strong>{sensors.length ? Math.round((online / sensors.length) * 100) : 0}<small>%</small></strong><span>network online</span></div><div><span className="eyebrow">NETWORK SIGNAL</span><h2>{online} of {sensors.length} sensors online</h2><p>All readings are linked to a room, floor, and building.</p><div className="signal-line"><i style={{ width: `${sensors.length ? (online / sensors.length) * 100 : 0}%` }} /></div></div><span className="sensor-live"><i /> LIVE</span></article><article className="sensor-stat"><span className="sensor-stat-icon cyan"><Thermometer size={17} /></span><div><strong>{sensors.filter((sensor: any) => sensor.type === 'temperature').length}</strong><small>Temperature sensors</small></div></article><article className="sensor-stat"><span className="sensor-stat-icon green"><Droplets size={17} /></span><div><strong>{sensors.filter((sensor: any) => sensor.type === 'humidity').length}</strong><small>Environmental sensors</small></div></article></div><div className="sensor-toolbar"><div><span className="eyebrow">DEVICE INVENTORY</span><strong>{visible.length} connected devices</strong></div><div className="sensor-filters"><button className={type === 'all' ? 'active' : ''} onClick={() => setType('all')}>All</button>{types.slice(0, 5).map((item: any) => <button className={type === item ? 'active' : ''} key={item} onClick={() => setType(item)}>{item.replace('_', ' ')}</button>)}</div></div><div className="sensor-workspace"><article className="panel sensor-inventory"><div className="sensor-table-head"><span>Sensor</span><span>Location</span><span>Latest signal</span><span>Status</span></div>{query.isLoading ? <div className="sensor-empty">Loading sensor telemetry...</div> : visible.map((sensor: any) => <button className={`sensor-row ${selected?.id === sensor.id ? 'selected' : ''}`} key={sensor.id} onClick={() => setSelected(sensor)}><span className="sensor-name"><i className={`sensor-type-dot ${sensor.type}`} /><strong>{sensor.code.split('-').slice(-1)[0].replace('_', ' ')}</strong><small>{sensor.type.replace('_', ' ')}</small></span><span className="sensor-location"><strong>{sensor.room}</strong><small>{sensor.building_code} · {sensor.floor}</small></span><span className="sensor-reading"><strong>{sensor.latest_value !== null ? `${Number(sensor.latest_value).toFixed(1)}${sensor.type === 'temperature' ? '°C' : sensor.type === 'humidity' ? '%' : ''}` : '--'}</strong><small>Updated recently</small></span><span className="sensor-status"><i className={sensor.status === 'ONLINE' ? 'online' : 'offline'} /> {sensor.status.toLowerCase()}</span></button>)}</article><aside className="sensor-detail-panel">{selected ? <><div className="sensor-detail-top"><span className="eyebrow">SELECTED SENSOR</span><span className="sensor-status"><i className="online" /> Online</span></div><div className="sensor-detail-icon"><Droplets size={22} /></div><h2>{selected.type.replace('_', ' ')} sensor</h2><p className="sensor-code">{selected.code}</p><div className="sensor-location-card"><MapPin size={15} /><span><small>Installed location</small><strong>{selected.room}</strong><em>{selected.floor} · {selected.building}</em></span></div><div className="sensor-detail-metrics"><Metric label="Latest reading" value={selected.latest_value !== null ? `${Number(selected.latest_value).toFixed(1)} ${selected.type === 'temperature' ? '°C' : selected.type === 'humidity' ? '%' : ''}` : '--'} /><Metric label="Signal status" value="Stable" /><Metric label="Reading rate" value="Every 5 min" /><Metric label="Device state" value="Online" /></div><div className="sensor-mini-chart"><span /><span /><span /><span /><span /><span /><span /><span /></div><small className="sensor-footnote"><Clock3 size={12} /> Last reading received recently</small></> : <div className="empty-state"><Gauge size={26} /><strong>Select a sensor</strong><p>Choose a device to inspect its location and current signal.</p></div>}</aside></div></> }
function HVACSection() { const query = useQuery({ queryKey: ['hvac'], queryFn: api.hvac }); const client = useQueryClient(); const [selected, setSelected] = useState<any>(); const mutation = useMutation({ mutationFn: (payload: any) => api.control(selected.id, payload), onSuccess: () => client.invalidateQueries({ queryKey: ['hvac'] }) }); return <><PageHeading eyebrow="HVAC CONTROL" title="Climate systems" copy="Control units through the protected backend control service." /><div className="control-layout"><div className="unit-list">{query.data?.slice(0, 12).map((unit: any) => <button className={selected?.id === unit.id ? 'unit active' : 'unit'} key={unit.id} onClick={() => setSelected(unit)}><span className="unit-icon"><Fan size={18} /></span><span><strong>{unit.code}</strong><small>{unit.mode} · {unit.health}% health</small></span><ChevronRight size={15} /></button>)}</div><article className="panel control-card">{selected ? <><span className="eyebrow">LIVE CONTROL</span><h2>{selected.code}</h2><p>Current setpoint {selected.setpoint}°C · {selected.status}</p><label>Setpoint <input type="range" min="16" max="32" defaultValue={selected.setpoint} onChange={(event) => mutation.mutate({ setpoint: Number(event.target.value) })} /></label><div className="control-actions">{['SMART_AUTO', 'COOL', 'ECO', 'OFF'].map((mode) => <button key={mode} className={selected.mode === mode ? 'selected' : ''} onClick={() => mutation.mutate({ mode })}>{mode}</button>)}</div>{mutation.isPending && <small className="muted">Sending command to backend...</small>}{mutation.isSuccess && <small className="success-text">Backend state updated.</small>}</> : <div className="empty-state"><Power size={26} /><strong>Select an HVAC unit</strong><p>Every control change is sent through the API and broadcast over WebSocket.</p></div>}</article></div></> }
function EnergySection() { const { data } = useQuery({ queryKey: ['energy'], queryFn: api.energy }); return <><PageHeading eyebrow="ENERGY INTELLIGENCE" title="Energy center" copy="Transparent consumption, cost, and estimated carbon impact." /><div className="metric-grid">{[['Current power', `${data?.current_power_kw ?? '--'} kW`], ["Today's energy", `${data?.today_kwh ?? '--'} kWh`], ['Estimated daily cost', `₹${data?.estimated_daily_cost ?? '--'}`], ['Carbon impact', `${data?.estimated_carbon_kg ?? '--'} kg`]].map(([label, value]) => <article className="metric-card" key={label}><div className="metric-label"><span>{label}</span><Zap size={16} /></div><strong>{value}</strong><small>Estimated from live HVAC telemetry</small></article>)}</div><article className="panel energy-bars"><PanelTitle eyebrow="USAGE TREND" title="Energy by period" />{[['Today', data?.today_kwh], ['This week', data?.week_kwh], ['This month', data?.month_kwh]].map(([label, value], index) => <div className="energy-row" key={label as string}><span>{label}</span><i style={{ width: `${35 + index * 25}%` }} /><b>{value ?? '--'} kWh</b></div>)}</article></> }
function AlertsSection() { const client = useQueryClient(); const query = useQuery({ queryKey: ['alerts'], queryFn: api.alerts }); const mutation = useMutation({ mutationFn: api.acknowledge, onSuccess: () => client.invalidateQueries({ queryKey: ['alerts'] }) }); return <><PageHeading eyebrow="ALERT OPERATIONS" title="Alerts" copy="Review and acknowledge issues generated from HVAC and sensor data." /><article className="panel alerts-list">{query.data?.map((alert: any) => <div className="alert-row" key={alert.id}><span className={`alert-icon ${alert.severity.toLowerCase()}`}><AlertTriangle size={17} /></span><div><strong>{alert.title}</strong><p>{alert.message}</p><small>{alert.severity} · {alert.status}</small></div>{alert.status === 'OPEN' && <button className="secondary-button" onClick={() => mutation.mutate(alert.id)}>Acknowledge</button>}</div>)}</article></> }
function AISection() { const [message, setMessage] = useState('Why is energy usage increasing?'); const [answer, setAnswer] = useState(''); const mutation = useMutation({ mutationFn: api.chat, onSuccess: (result) => setAnswer(result.answer) }); return <><PageHeading eyebrow="SMART HVAC AI" title="AI insights" copy="Ask questions answered from current application data. Responses are estimates, not instructions." /><article className="panel ai-panel"><div className="ai-orb"><Bot size={28} /></div><h2>What would you like to understand?</h2><p>Try “Which room is hottest?” or “Which HVAC unit needs attention?”</p><div className="ai-input"><input value={message} onChange={(event) => setMessage(event.target.value)} /><button className="primary-button" onClick={() => mutation.mutate(message)}>{mutation.isPending ? 'Thinking...' : 'Ask AI'} <ChevronRight size={15} /></button></div>{answer && <div className="ai-answer"><span className="eyebrow">DATA-BACKED RESPONSE</span><p>{answer}</p></div>}</article></> }

function UsersSection() {
  const [user, setUser] = useState({ name: '', email: '', password: '', role: 'EMPLOYEE' });
  const [selectedUser, setSelectedUser] = useState<any>();
  const query = useQuery({ queryKey: ['users'], queryFn: api.users });
  const mutation = useMutation({ mutationFn: api.createUser, onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['users'] }); setUser({ name: '', email: '', password: '', role: 'EMPLOYEE' }); } });
  const activeUser = selectedUser || query.data?.[0];
  return <>
    <PageHeading eyebrow="ACCESS CONTROL" title="People and permissions" copy="Understand who has access, where they work, and what they can manage." />
    <div className="user-summary-grid"><article className="profile-summary"><div className="profile-avatar">{activeUser?.name?.slice(0, 2).toUpperCase() || 'US'}</div><div><span className="eyebrow">SELECTED PROFILE</span><h2>{activeUser?.name || 'No user selected'}</h2><p>{activeUser?.role?.replaceAll('_', ' ') || 'Choose a user to view details'}</p></div><span className="account-status"><i /> Active</span></article><article className="mini-stat"><span><Users size={16} /></span><div><strong>{query.data?.length ?? 0}</strong><small>Organization users</small></div></article><article className="mini-stat"><span><ShieldCheck size={16} /></span><div><strong>3</strong><small>Access levels</small></div></article></div>
    <div className="user-workspace">
      <article className="panel user-directory"><div className="directory-heading"><PanelTitle eyebrow="DIRECTORY" title="Organization users" /><span className="directory-filter">All users <ChevronRight size={13} /></span></div><div className="user-list user-list-expanded">{query.data?.map((item: any) => <button className={`user-row ${activeUser?.id === item.id ? 'selected' : ''}`} key={item.id} onClick={() => setSelectedUser(item)}><span className="avatar">{item.name.slice(0, 2).toUpperCase()}</span><div><strong>{item.name}</strong><small>{item.email}</small></div><span className={`role-chip ${item.role.toLowerCase()}`}>{item.role.replaceAll('_', ' ')}</span><span className="presence-dot" /></button>)}</div></article>
      <aside className="user-profile-panel"><div className="profile-panel-top"><span className="eyebrow">USER DETAILS</span><button aria-label="More user actions">•••</button></div><div className="profile-identity"><div className="profile-avatar large">{activeUser?.name?.slice(0, 2).toUpperCase() || 'US'}</div><h2>{activeUser?.name || 'Select a user'}</h2><p>{activeUser?.email || 'User information will appear here'}</p><span className="role-chip admin">{activeUser?.role?.replaceAll('_', ' ') || '—'}</span></div><div className="profile-detail-list"><div><MapPin size={15} /><span><small>Organization</small><strong>SmartHVAC Demo Organization</strong></span></div><div><Building2 size={15} /><span><small>Primary location</small><strong>Chennai Operations Campus</strong></span></div><div><UserRound size={15} /><span><small>Organization ID</small><strong>{activeUser?.organization_id?.slice(0, 14) || 'Global access'}</strong></span></div><div><Clock3 size={15} /><span><small>Last active</small><strong>Today · 10:42 AM</strong></span></div></div><div className="profile-access"><div><span>Access scope</span><b>{activeUser?.role === 'SUPERADMIN' ? 'All organizations' : 'One organization'}</b></div><div className="scope-bar"><i style={{ width: activeUser?.role === 'SUPERADMIN' ? '100%' : '38%' }} /></div><p>{activeUser?.role === 'SUPERADMIN' ? 'Global platform administration and organization management.' : 'Buildings, HVAC, energy, alerts, and users within this organization.'}</p></div><div className="profile-actions"><button><Bell size={14} /> Notifications</button><button><MapPin size={14} /> View location</button></div></aside>
    </div>
    <article className="panel create-user-panel"><div><PanelTitle eyebrow="ADD TO ORGANIZATION" title="Create a new user" /><p className="panel-copy">New accounts inherit your organization scope and can be assigned a controlled role.</p></div><form className="user-form inline-user-form" onSubmit={(event) => { event.preventDefault(); mutation.mutate(user); }}><input required placeholder="Full name" value={user.name} onChange={(event) => setUser({ ...user, name: event.target.value })} /><input required type="email" placeholder="Email address" value={user.email} onChange={(event) => setUser({ ...user, email: event.target.value })} /><input required minLength={8} type="password" placeholder="Temporary password" value={user.password} onChange={(event) => setUser({ ...user, password: event.target.value })} /><select value={user.role} onChange={(event) => setUser({ ...user, role: event.target.value })}><option value="EMPLOYEE">Employee</option><option value="FACILITY_MANAGER">Facility manager</option><option value="ADMIN">Admin</option></select><button className="primary-button" disabled={mutation.isPending}><ShieldCheck size={15} /> {mutation.isPending ? 'Creating...' : 'Create user'}</button></form>{mutation.isError && <small className="error-text">{String((mutation.error as any)?.response?.data?.detail || 'Unable to create user')}</small>}</article>
  </>;
}

function ReportsRedesign() { const energy = useQuery({ queryKey: ['energy'], queryFn: api.energy }); const alerts = useQuery({ queryKey: ['alerts'], queryFn: api.alerts }); const buildings = useQuery({ queryKey: ['locations'], queryFn: api.locations }); const [range, setRange] = useState('This month'); const [exported, setExported] = useState(false); const exportReport = () => { const rows = [['SmartHVAC operational report', range], ['Buildings', buildings.data?.length || 0], ['Energy today (kWh)', energy.data?.today_kwh || 0], ['Energy this month (kWh)', energy.data?.month_kwh || 0], ['Estimated cost', energy.data?.estimated_daily_cost || 0], ['Open alerts', alerts.data?.filter((alert: any) => alert.status === 'OPEN').length || 0]]; const csv = rows.map((row) => row.join(',')).join('\n'); const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv' })); link.download = `smarthvac-${range.toLowerCase().replace(' ', '-')}-report.csv`; link.click(); URL.revokeObjectURL(link.href); setExported(true); setTimeout(() => setExported(false), 1800); }; return <><PageHeading eyebrow="OPERATIONAL REPORTING" title="Reports" copy="Turn building telemetry into a clear record for decisions, audits, and follow-up." /><div className="report-hero"><div><span className="eyebrow">REPORT BUILDER</span><h2>{range} performance report</h2><p>Temperature, energy, HVAC health, alerts, and estimated cost.</p></div><div className="report-actions"><select value={range} onChange={(event) => setRange(event.target.value)}><option>Today</option><option>This week</option><option>This month</option><option>Last 30 days</option></select><button className="primary-button" onClick={exportReport}><Download size={14} /> {exported ? 'Downloaded' : 'Export CSV'}</button></div></div><div className="report-layout"><article className="panel report-preview"><div className="report-preview-head"><PanelTitle eyebrow="REPORT PREVIEW" title="Building performance" /><span className="report-status"><i /> Ready to export</span></div><div className="report-metrics"><Metric label="Energy today" value={energy.data ? `${energy.data.today_kwh} kWh` : '--'} /><Metric label="Estimated cost" value={energy.data ? `₹${energy.data.estimated_daily_cost}` : '--'} /><Metric label="Carbon impact" value={energy.data ? `${energy.data.estimated_carbon_kg} kg` : '--'} /><Metric label="Open alerts" value={alerts.data?.filter((alert: any) => alert.status === 'OPEN').length ?? '--'} /></div><div className="report-bars"><div><span>Energy performance</span><i><em style={{ width: '76%' }} /></i><b>76 / 100</b></div><div><span>Comfort coverage</span><i><em style={{ width: '91%' }} /></i><b>91 / 100</b></div><div><span>HVAC availability</span><i><em style={{ width: '94%' }} /></i><b>94 / 100</b></div></div></article><aside className="panel report-sections"><PanelTitle eyebrow="INCLUDED SECTIONS" title="Report contents" />{[['Energy & cost', Zap], ['Comfort & environment', Thermometer], ['HVAC health', Fan], ['Alerts & maintenance', AlertTriangle]].map(([label, Icon]) => <div key={label as string}><Icon size={15} /><span>{label as string}</span><b>Included</b></div>)}</aside></div></> }

function SettingsRedesign() { const [settings, setSettings] = useState(() => JSON.parse(localStorage.getItem('smarthvac_settings') || '{"temperature":"26","humidity":"60","co2":"1000","tariff":"8","notifications":true,"demo":true}')); const [saved, setSaved] = useState(false); const update = (key: string, value: any) => setSettings({ ...settings, [key]: value }); const save = () => { localStorage.setItem('smarthvac_settings', JSON.stringify(settings)); setSaved(true); setTimeout(() => setSaved(false), 1800); }; return <><PageHeading eyebrow="PLATFORM CONFIGURATION" title="Settings" copy="Tune comfort policies, notifications, and the connections that keep SmartHVAC reliable." /><div className="settings-layout"><div className="settings-main"><article className="panel settings-card"><div className="settings-card-head"><div><span className="eyebrow">COMFORT POLICY</span><h2>Environment thresholds</h2><p>These values guide alerts and Smart Auto recommendations.</p></div><SlidersHorizontal size={19} /></div><div className="settings-fields"><label>High temperature alert<input type="number" value={settings.temperature} onChange={(event) => update('temperature', event.target.value)} /><small>°C · Alert when room temperature exceeds this value</small></label><label>High humidity alert<input type="number" value={settings.humidity} onChange={(event) => update('humidity', event.target.value)} /><small>% · Recommended comfort ceiling</small></label><label>CO₂ threshold<input type="number" value={settings.co2} onChange={(event) => update('co2', event.target.value)} /><small>ppm · Indoor air quality limit</small></label><label>Electricity tariff<input type="number" value={settings.tariff} onChange={(event) => update('tariff', event.target.value)} /><small>₹ / kWh · Used in energy estimates</small></label></div></article><article className="panel settings-card"><div className="settings-card-head"><div><span className="eyebrow">NOTIFICATIONS</span><h2>Stay informed</h2><p>Choose which operational updates appear in your workspace.</p></div><Bell size={19} /></div><div className="settings-toggle-row"><div><strong>Alert notifications</strong><small>Receive critical and warning HVAC events</small></div><button className={`toggle ${settings.notifications ? 'on' : ''}`} onClick={() => update('notifications', !settings.notifications)}><i /></button></div><div className="settings-toggle-row"><div><strong>Demo simulator</strong><small>Generate realistic telemetry without hardware</small></div><button className={`toggle ${settings.demo ? 'on' : ''}`} onClick={() => update('demo', !settings.demo)}><i /></button></div></article></div><aside className="settings-side"><article className="panel connection-card"><PanelTitle eyebrow="CONNECTIONS" title="System status" /><div><Database size={16} /><span><strong>Database</strong><small>SQLite demo store · Connected</small></span><i className="connection-dot" /></div><div><Zap size={16} /><span><strong>Telemetry simulator</strong><small>{settings.demo ? 'Generating live updates' : 'Paused by workspace setting'}</small></span><i className={`connection-dot ${settings.demo ? '' : 'paused'}`} /></div><div><MapPin size={16} /><span><strong>Google Maps</strong><small>Configured through environment</small></span><i className="connection-dot paused" /></div></article><article className="panel save-settings"><ShieldCheck size={20} /><strong>Configuration is local</strong><p>Changes are stored for this browser session and can be adjusted without restarting the dashboard.</p><button className="primary-button" onClick={save}><Save size={14} /> {saved ? 'Settings saved' : 'Save settings'}</button></article></aside></div></> }

function AlertsRedesign() { const client = useQueryClient(); const query = useQuery({ queryKey: ['alerts'], queryFn: api.alerts, refetchInterval: 10000 }); const mutation = useMutation({ mutationFn: api.acknowledge, onSuccess: () => client.invalidateQueries({ queryKey: ['alerts'] }) }); const alerts = query.data || []; const open = alerts.filter((alert: any) => alert.status === 'OPEN'); return <><PageHeading eyebrow="INCIDENT OPERATIONS" title="Alert center" copy="Triage the signals that need a human decision, then close the loop." /><div className="alert-overview"><div><span className="eyebrow">OPEN NOW</span><strong>{open.length}</strong><small>Signals requiring attention</small></div><div><span className="eyebrow">CRITICAL</span><strong>{open.filter((alert: any) => alert.severity === 'CRITICAL').length}</strong><small>Immediate review recommended</small></div><div><span className="eyebrow">ACKNOWLEDGED</span><strong>{alerts.filter((alert: any) => alert.status !== 'OPEN').length}</strong><small>Already reviewed</small></div></div><div className="alerts-redesign-layout"><article className="panel alert-feed"><div className="alert-feed-head"><PanelTitle eyebrow="LIVE FEED" title="Recent signals" /><span className="live-pill"><i /> STREAMING</span></div>{alerts.map((alert: any) => <div className={`alert-card ${alert.severity.toLowerCase()}`} key={alert.id}><span className="alert-card-icon"><AlertTriangle size={17} /></span><div><div className="alert-card-title"><strong>{alert.title}</strong><span>{alert.severity}</span></div><p>{alert.message}</p><small>{new Date(alert.created_at).toLocaleString()} · {alert.status.toLowerCase()}</small></div>{alert.status === 'OPEN' && <button className="secondary-button" onClick={() => mutation.mutate(alert.id)}>Acknowledge</button>}</div>)}</article><aside className="panel alert-guidance"><PanelTitle eyebrow="RESPONSE GUIDE" title="Triage by severity" /><div><span className="guidance-dot critical" /><strong>Critical</strong><p>Pause automated changes and inspect the affected equipment.</p></div><div><span className="guidance-dot warning" /><strong>Warning</strong><p>Review the trend and schedule follow-up work.</p></div><div><span className="guidance-dot info" /><strong>Information</strong><p>Keep the signal visible for operational context.</p></div></aside></div></> }

function SchedulingRedesign() { const hvac = useQuery({ queryKey: ['hvac'], queryFn: api.hvac }); const [mode, setMode] = useState('ECO'); const [saved, setSaved] = useState(false); return <><PageHeading eyebrow="AUTOMATION CALENDAR" title="HVAC scheduling" copy="Shape recurring comfort and energy behavior around your building rhythm." /><div className="schedule-hero"><div><span className="eyebrow">WEEKDAY PROFILE</span><h2>Occupied hours</h2><p>Monday–Friday · 08:30 to 17:30</p></div><div className="schedule-days"><span className="active">M</span><span className="active">T</span><span className="active">W</span><span className="active">T</span><span className="active">F</span><span>S</span><span>S</span></div><b>ACTIVE</b></div><div className="schedule-layout"><article className="panel schedule-editor"><PanelTitle eyebrow="SCHEDULE EDITOR" title="Comfort timeline" /><div className="schedule-timeline"><div><span>06:00</span><i /></div><div className="occupied"><span>08:30</span><i /><b>Comfort mode</b></div><div className="occupied"><span>17:30</span><i /><b>Eco mode</b></div><div><span>22:00</span><i /></div></div><div className="schedule-form"><label>Target mode<select value={mode} onChange={(event) => setMode(event.target.value)}><option>SMART_AUTO</option><option>COMFORT</option><option>ECO</option><option>OFF</option></select></label><label>Apply to<select><option>All HVAC units</option>{hvac.data?.slice(0, 5).map((unit: any) => <option key={unit.id}>{unit.code}</option>)}</select></label><button className="primary-button" onClick={() => setSaved(true)}>{saved ? 'Schedule saved' : 'Save schedule'} <ChevronRight size={14} /></button></div></article><aside className="panel upcoming-schedule"><PanelTitle eyebrow="UP NEXT" title="Automation queue" /><div><span>Today · 08:30</span><strong>Comfort mode ON</strong><small>All occupied zones</small></div><div><span>Today · 17:30</span><strong>Eco mode ON</strong><small>Energy-saving profile</small></div><div><span>Tomorrow · 08:30</span><strong>Comfort mode ON</strong><small>Weekday profile</small></div></aside></div></> }

function ServiceRequestsRedesign() { const [requests, setRequests] = useState([{ id: 'SR-1042', title: 'Room 204 feels warm', location: 'Building 01 · Floor 2', priority: 'HIGH', status: 'OPEN', time: '12 min ago' }, { id: 'SR-1041', title: 'Unusual HVAC noise', location: 'Building 03 · Room 306', priority: 'NORMAL', status: 'ASSIGNED', time: '1 hr ago' }]); const [form, setForm] = useState({ title: '', location: 'Building 01 · Floor 2', priority: 'NORMAL' }); const submit = (event: React.FormEvent) => { event.preventDefault(); if (!form.title.trim()) return; setRequests([{ id: `SR-${1043 + requests.length}`, title: form.title, location: form.location, priority: form.priority, status: 'OPEN', time: 'just now' }, ...requests]); setForm({ ...form, title: '' }); }; return <><PageHeading eyebrow="FIELD OPERATIONS" title="Service requests" copy="Give occupants a clear path to report comfort issues and follow progress." /><div className="request-overview"><div><span className="eyebrow">OPEN REQUESTS</span><strong>{requests.filter((request) => request.status !== 'RESOLVED').length}</strong><small>Across managed spaces</small></div><div><span className="eyebrow">HIGH PRIORITY</span><strong>{requests.filter((request) => request.priority === 'HIGH').length}</strong><small>Needs rapid response</small></div><div><span className="eyebrow">AVG RESPONSE</span><strong>18m</strong><small>Last 7 days</small></div></div><div className="request-layout"><article className="panel request-form-panel"><PanelTitle eyebrow="NEW REQUEST" title="Report a building issue" /><form onSubmit={submit}><label>What needs attention?<input required placeholder="e.g. Room is too warm" value={form.title} onChange={(event) => setForm({ ...form, title: event.target.value })} /></label><label>Location<select value={form.location} onChange={(event) => setForm({ ...form, location: event.target.value })}><option>Building 01 · Floor 2</option><option>Building 02 · Floor 1</option><option>Building 03 · Room 306</option></select></label><label>Priority<select value={form.priority} onChange={(event) => setForm({ ...form, priority: event.target.value })}><option>NORMAL</option><option>HIGH</option><option>URGENT</option></select></label><button className="primary-button">Submit request <ChevronRight size={14} /></button></form></article><article className="panel request-list"><PanelTitle eyebrow="REQUEST TRACKER" title="Recent requests" />{requests.map((request) => <div className="request-card" key={request.id}><span className={`request-priority ${request.priority.toLowerCase()}`} /><div><div><strong>{request.title}</strong><span>{request.id}</span></div><p>{request.location} · {request.time}</p></div><b className={request.status.toLowerCase()}>{request.status}</b></div>)}</article></div></> }

function HVACControlRedesign() { const query = useQuery({ queryKey: ['hvac'], queryFn: api.hvac, refetchInterval: 10000 }); const client = useQueryClient(); const [selected, setSelected] = useState<any>(); const mutation = useMutation({ mutationFn: (payload: any) => api.control(selected.id, payload), onSuccess: (updated) => { setSelected(updated); client.invalidateQueries({ queryKey: ['hvac'] }); } }); const units = query.data || []; const active = units.filter((unit: any) => unit.mode !== 'OFF').length; return <><PageHeading eyebrow="HVAC COMMAND" title="Control room" copy="Make precise changes to live systems with clear state and safety feedback." /><div className="hvac-overview"><div><span className="eyebrow">ACTIVE UNITS</span><strong>{active}<small> / {units.length}</small></strong><p>Currently delivering climate control</p></div><div><span className="eyebrow">SMART AUTO</span><strong>{units.filter((unit: any) => unit.mode === 'SMART_AUTO').length}</strong><p>Units optimizing automatically</p></div><div><span className="eyebrow">ATTENTION</span><strong>{units.filter((unit: any) => unit.health < 80).length}</strong><p>Health below 80%</p></div></div><div className="hvac-control-layout"><article className="panel hvac-unit-rail"><div className="panel-title"><div><span className="eyebrow">EQUIPMENT FLEET</span><h2>Live units</h2></div><span className="live-pill"><i /> LIVE</span></div><div className="hvac-unit-list">{units.slice(0, 18).map((unit: any) => <button className={selected?.id === unit.id ? 'selected' : ''} key={unit.id} onClick={() => setSelected(unit)}><span className={`unit-state ${unit.mode === 'OFF' ? 'off' : unit.health < 80 ? 'warn' : ''}`} /><span><strong>{unit.code}</strong><small>{unit.mode.replace('_', ' ')} · {unit.health}% health</small></span><b>{unit.power.toFixed(1)} kW</b></button>)}</div></article><article className="panel hvac-console">{selected ? <><div className="console-header"><div><span className="eyebrow">SELECTED UNIT</span><h2>{selected.code}</h2><p>Room-linked controller · {selected.status}</p></div><span className="console-health">{selected.health}%<small>health</small></span></div><div className="setpoint-readout"><span>Target temperature</span><strong>{selected.setpoint}°C</strong><small>Comfort range 22–26°C</small></div><input className="temperature-slider" type="range" min="16" max="32" step="0.5" value={selected.setpoint} onChange={(event) => mutation.mutate({ setpoint: Number(event.target.value) })} /><div className="mode-heading"><span>Operating mode</span><small>Changes are sent to the backend</small></div><div className="mode-grid">{['SMART_AUTO', 'COOL', 'HEAT', 'FAN', 'ECO', 'OFF'].map((mode) => <button className={selected.mode === mode ? 'active' : ''} key={mode} onClick={() => mutation.mutate({ mode })}>{mode.replace('_', ' ')}</button>)}</div><div className="console-footer"><span><i className="online-dot" /> Command channel secure</span>{mutation.isPending ? <b>Sending update...</b> : mutation.isSuccess ? <b>State synchronized</b> : <small>Last update just now</small>}</div></> : <div className="empty-state"><Fan size={28} /><strong>Select an HVAC unit</strong><p>Choose a unit to view its live state and make a controlled change.</p></div>}</article></div></> }

function EnergyRedesign() { const { data, isLoading } = useQuery({ queryKey: ['energy'], queryFn: api.energy, refetchInterval: 15000 }); const [reduction, setReduction] = useState(10); const today = data?.today_kwh || 0; return <><PageHeading eyebrow="ENERGY INTELLIGENCE" title="Energy command center" copy="Turn live consumption into practical savings decisions." /><div className="energy-hero"><div><span className="eyebrow">TODAY'S CONSUMPTION</span><h2>{isLoading ? '--' : `${today} kWh`}</h2><p>Estimated from current HVAC telemetry</p></div><div className="energy-hero-chart"><span /><span /><span /><span /><span /><span /><span /><span /><span /><span /></div><div className="energy-hero-badge"><Zap size={17} /><strong>{data?.current_power_kw ?? '--'} kW</strong><small>Current draw</small></div></div><div className="energy-kpis"><Metric label="This week" value={data ? `${data.week_kwh} kWh` : '--'} /><Metric label="This month" value={data ? `${data.month_kwh} kWh` : '--'} /><Metric label="Estimated cost" value={data ? `₹${data.estimated_daily_cost}` : '--'} /><Metric label="Carbon impact" value={data ? `${data.estimated_carbon_kg} kg` : '--'} /></div><div className="energy-redesign-grid"><article className="panel energy-breakdown"><PanelTitle eyebrow="CONSUMPTION PROFILE" title="Usage by period" />{[['Today', data?.today_kwh, 42], ['This week', data?.week_kwh, 68], ['This month', data?.month_kwh, 88]].map(([label, value, width]) => <div className="energy-profile-row" key={label as string}><div><strong>{label}</strong><span>{value ?? '--'} kWh</span></div><i><em style={{ width: `${width}%` }} /></i><small>{label === 'Today' ? 'Live' : 'Compared with baseline'}</small></div>)}</article><article className="panel energy-simulator"><span className="eyebrow">WHAT-IF SIMULATOR</span><h2>Reduce HVAC demand</h2><p>Estimate the impact of a more efficient operating profile.</p><div className="what-if-values"><div><small>Current</small><strong>{today.toFixed(1)} kWh</strong></div><ChevronRight size={17} /><div><small>Projected</small><strong>{(today * (1 - reduction / 100)).toFixed(1)} kWh</strong></div></div><label>Reduction target <b>{reduction}%</b><input type="range" min="0" max="30" value={reduction} onChange={(event) => setReduction(Number(event.target.value))} /></label><div className="saving-callout"><Lightbulb size={16} /><span>Potential saving <strong>{(today * reduction / 100).toFixed(1)} kWh/day</strong></span></div></article></div></> }

function AIInsightsRedesign() { const [message, setMessage] = useState('Summarize today’s building performance'); const [answer, setAnswer] = useState(''); const mutation = useMutation({ mutationFn: api.chat, onSuccess: (result) => setAnswer(result.answer) }); const prompts = ['Why is energy usage increasing?', 'Which HVAC unit needs attention?', 'Which room is hottest?']; return <><PageHeading eyebrow="DECISION SUPPORT" title="AI insights" copy="Ask SmartHVAC to explain live conditions using the current platform data." /><div className="ai-insight-layout"><article className="panel ai-command-panel"><div className="ai-command-hero"><div className="ai-orb"><Bot size={28} /></div><div><span className="eyebrow">SMART HVAC AI</span><h2>Make the network easier to understand.</h2><p>Answers are grounded in current telemetry and clearly labeled as estimates.</p></div></div><div className="ai-prompt-chips">{prompts.map((prompt) => <button key={prompt} onClick={() => setMessage(prompt)}>{prompt}</button>)}</div><div className="ai-input"><input value={message} onChange={(event) => setMessage(event.target.value)} /><button className="primary-button" onClick={() => mutation.mutate(message)}>{mutation.isPending ? 'Analyzing...' : 'Ask SmartHVAC'} <ChevronRight size={15} /></button></div>{answer ? <div className="ai-answer ai-answer-large"><span className="eyebrow">CURRENT DATA RESPONSE</span><p>{answer}</p><small>Generated from live application data · Estimate</small></div> : <div className="ai-empty"><Bot size={20} /><span>Choose a prompt or ask about comfort, energy, or maintenance.</span></div>}</article><aside className="panel ai-context-panel"><PanelTitle eyebrow="CONTEXT USED" title="What AI can see" /><div><span><Thermometer size={15} /> Environment</span><b>Room temperatures and humidity</b></div><div><span><Zap size={15} /> Energy</span><b>Current and historical consumption</b></div><div><span><Fan size={15} /> HVAC</span><b>Modes, health, and runtime state</b></div><div><AlertTriangle size={15} /><span>Alerts</span><b>Open anomalies and priorities</b></div></aside></div></> }

function MaintenanceRedesign() { const hvac = useQuery({ queryKey: ['hvac'], queryFn: api.hvac }); const alerts = useQuery({ queryKey: ['alerts'], queryFn: api.alerts }); const units = hvac.data || []; const attention = units.filter((unit: any) => unit.health < 85).sort((a: any, b: any) => a.health - b.health); return <><PageHeading eyebrow="RELIABILITY OPERATIONS" title="Maintenance" copy="Prioritize equipment work from health signals before comfort becomes an incident." /><div className="maintenance-kpis"><div><span className="eyebrow">OPEN WORK</span><strong>{attention.length}</strong><small>Units need review</small></div><div><span className="eyebrow">HIGH PRIORITY</span><strong>{attention.filter((unit: any) => unit.health < 75).length}</strong><small>Health below 75%</small></div><div><span className="eyebrow">OPEN ALERTS</span><strong>{alerts.data?.filter((alert: any) => alert.status === 'OPEN').length ?? '--'}</strong><small>Needs acknowledgment</small></div></div><div className="maintenance-layout"><article className="panel maintenance-queue"><PanelTitle eyebrow="PRIORITIZED QUEUE" title="Recommended work" />{attention.length ? attention.map((unit: any, index: number) => <div className="maintenance-row" key={unit.id}><span className={`priority-number ${index === 0 ? 'urgent' : ''}`}>{String(index + 1).padStart(2, '0')}</span><div><strong>{unit.code}</strong><p>{unit.health < 75 ? 'Inspect compressor performance and vibration.' : 'Review runtime against room comfort profile.'}</p><small>SMART HVAC · {unit.mode.replace('_', ' ')}</small></div><span className={`maintenance-health ${unit.health < 75 ? 'critical' : 'warning'}`}>{unit.health}% health</span><button className="secondary-button">Create ticket</button></div>) : <div className="empty-state"><ShieldCheck size={26} /><strong>All systems healthy</strong><p>No units currently require maintenance review.</p></div>}</article><aside className="panel maintenance-side"><PanelTitle eyebrow="MAINTENANCE SIGNAL" title="Why this matters" /><div className="maintenance-signal"><span className="signal-icon"><AlertTriangle size={17} /></span><div><strong>Health trends are predictive</strong><p>Priorities are based on current HVAC health and operating mode. They are recommendations, not confirmed failures.</p></div></div><div className="maintenance-steps"><span><i>1</i> Review health trend</span><span><i>2</i> Assign a technician</span><span><i>3</i> Resolve and document</span></div></aside></div></> }

createRoot(document.getElementById('root')!).render(<React.StrictMode><QueryClientProvider client={queryClient}><App /></QueryClientProvider></React.StrictMode>);
